// ================================================================
// SOLR CATALOG METADATA TOOL — FLOWISE CUSTOM TOOL
// Answers catalog discovery queries (brands, models, categories,
// types) directly from pre-built knowledge — no Solr call needed.
// Input variable: $searchQuery
// ================================================================

// ── INTENT DETECTION ────────────────────────────────────────────
function detectCatalogIntent(query) {
  const q = query.toLowerCase().trim();

  const isCatalogQuery =
    /what .*(do you have|are available|can i find|brands?|types?|models?|categories|styles?|options)|list (all|available|the |\w[\w\s]*(brands?|models?|categor\w+|types?|styles?))|show (?!me )(\w[\w\s]*(types?|categor\w+|brands?|styles?|models?))|which .*(brands?|models?|types?|are)|what kinds? of|available (brands?|types?|models?|categor\w+)|how many (brands?|models?|types?)|\b(list|show) \w[\w\s]{0,40}(models?|brands?|categor\w+|types?|styles?)$/.test(q);

  if (!isCatalogQuery) return null;

  const wantsBrands     = /(brand|company|companies|make|manufacturer)/.test(q);
  const wantsModels     = /(model|version|variant|series|lineup|phone model)/.test(q);
  const wantsCategories = /(categor|collection|section|department|type|kind|style|subcategor)/.test(q);

  const isMobile    = /(mobile|phone|smartphone|iphone|samsung|oneplus|xiaomi|redmi|oppo|vivo|motorola|realme|nothing|pixel|android|5g phone)/.test(q);
  const isAccessory = /(accessory|accessories|case|cover|charger|earphone|headphone|screen protector|cable)/.test(q);
  const isShoe      = /(shoe|footwear|sneaker|boot|sandal|slipper|loafer|heel|flat|pump|formal shoe|casual shoe|running shoe|sport shoe|trek|hiking)/.test(q);
  const isApparel   = /(cloth|apparel|wear|shirt|tshirt|t-shirt|trouser|pant|jean|dress|kurta|saree|top|jacket|sweatshirt|hoodie|sweater|suit|blazer|kurti|ethnic|lingerie)/.test(q);
  const isMen       = /\bmen\b|\bman\b|\bgents\b|\bmenswear\b/.test(q);
  const isWomen     = /\bwomen\b|\bwoman\b|\bladies\b|\bfemale\b/.test(q);
  const isKids      = /\bkid\b|\bkids\b|\bchild\b|\bboy\b|\bgirl\b|\bbaby\b/.test(q);

  const brandModelMap = {
    samsung: 'samsung', apple: 'apple', iphone: 'apple',
    oneplus: 'oneplus', xiaomi: 'xiaomi', redmi: 'xiaomi',
    oppo: 'oppo', vivo: 'vivo', motorola: 'motorola',
    realme: 'realme', nothing: 'nothing', pixel: 'pixel',
  };
  let specificBrand = null;
  for (const [keyword, brand] of Object.entries(brandModelMap)) {
    if (q.includes(keyword)) { specificBrand = brand; break; }
  }

  return { wantsBrands, wantsModels, wantsCategories, isMobile, isAccessory, isShoe, isApparel, isMen, isWomen, isKids, specificBrand };
}

