// ── RESPONSE BUILDER ─────────────────────────────────────────────
function buildResponse(intent, originalQuery) {
  const { wantsBrands, wantsModels, wantsCategories, isMobile, isAccessory, isShoe, isApparel, isMen, isWomen, isKids, specificBrand } = intent;
  const q = originalQuery.toLowerCase();

  // ═══ MOBILE — MODELS ═══════════════════════════════════════
  if (isMobile && wantsModels && specificBrand) {
    const models = CATALOG.mobile.models[specificBrand];
    if (!models || models.length === 0) return { type: 'catalog', answer: `We have limited model data for that brand. Try searching by brand name to see available products.` };
    const labels = { samsung:'Samsung Galaxy', apple:'Apple iPhone', oneplus:'OnePlus', xiaomi:'Xiaomi / Redmi', realme:'Realme', oppo:'OPPO', motorola:'Motorola / Moto', vivo:'Vivo', nothing:'Nothing', pixel:'Google Pixel' };
    return { type: 'models', domain: `${labels[specificBrand] || specificBrand} Models Available`, items: models, note: 'Search by model name to see prices, ratings, and full details.' };
  }

  // ═══ MOBILE — BRANDS ═══════════════════════════════════════
  if (isMobile && !isAccessory && (wantsBrands || (!wantsModels && !wantsCategories))) {
    return { type: 'brands', domain: 'Smartphone Brands', items: CATALOG.mobile.smartphoneBrands, extra: { 'Feature Phone Brands': CATALOG.mobile.featurePhoneBrands }, note: 'Search by brand name to see all available models.' };
  }

  // ═══ ACCESSORIES ═══════════════════════════════════════════
  if (isAccessory) {
    if ((q.includes('iphone') || q.includes('apple')) && (q.includes('case') || q.includes('cover'))) {
      return { type: 'models', domain: 'iPhone Cases & Covers — Models Available For', items: CATALOG.mobile.accessories.iphoneCaseModels, note: 'We also carry generic iPhone-compatible cases. Search by model for exact matches.' };
    }
    if (q.includes('samsung') && (q.includes('case') || q.includes('cover'))) {
      return { type: 'models', domain: 'Samsung Cases & Covers — Models Available For', items: CATALOG.mobile.accessories.samsungCaseModels, note: 'We also carry generic Galaxy-compatible cases. Search by model (e.g. "S23 case") for exact matches.' };
    }
    if (q.includes('case') || q.includes('cover')) {
      if (wantsBrands) return { type: 'brands', domain: 'Phone Case & Cover Brands', items: CATALOG.mobile.accessories.caseBrands };
      return { type: 'categories', domain: 'Phone Case & Cover Types', items: CATALOG.mobile.accessories.caseTypes };
    }
    if (q.includes('screen')) {
      if (wantsBrands) return { type: 'brands', domain: 'Screen Protector Brands', items: CATALOG.mobile.accessories.screenProtectorBrands };
    }
    if (q.includes('charger') || q.includes('cable')) {
      if (wantsBrands) return { type: 'brands', domain: 'Charger Brands', items: CATALOG.mobile.accessories.chargerBrands };
    }
    if (q.includes('earphone') || q.includes('headphone') || q.includes('audio')) {
      if (wantsBrands) return { type: 'brands', domain: 'Audio Accessory Brands', items: CATALOG.mobile.accessories.audioBrands };
    }
    return { type: 'categories', domain: 'Mobile Accessories Categories', items: CATALOG.mobile.categories.filter(c => !c.startsWith('Smartphone') && !c.startsWith('Feature')), note: 'Add a phone model to narrow down (e.g. "S23 cases", "iPhone 14 screen protector").' };
  }

  // ═══ MOBILE — CATEGORIES ══════════════════════════════════
  if (isMobile && wantsCategories) {
    return { type: 'categories', domain: 'Mobile Phones & Accessories — All Categories', items: CATALOG.mobile.categories, subcategories: { 'Smartphone Types': CATALOG.mobile.smartphoneTypes } };
  }

  // ═══ SHOES — BRANDS ═══════════════════════════════════════
  if (isShoe && wantsBrands) {
    if (q.includes('loafer')) return { type: 'brands', domain: 'Loafer Brands', items: ['Clarks','Sperry','Skechers','Crocs','Hush Puppies','Bruno Marc'] };
    if (q.includes('sneaker')) return { type: 'brands', domain: 'Sneaker Brands', items: ['Nike','Adidas','PUMA','Reebok','Vans','Converse','ASICS','New Balance','Skechers'] };
    if (q.includes('formal')) return { type: 'brands', domain: 'Formal Shoe Brands', items: ['Clarks','Bruno Marc','Anthony Veer','Timberland'] };
    if (q.includes('running') || q.includes('sport')) return { type: 'brands', domain: 'Sports Shoe Brands', items: ['Nike','Adidas','ASICS','New Balance','Skechers','Under Armour','Reebok','PUMA','Merrell','Salomon'] };
    return { type: 'brands', domain: 'Shoe & Footwear Brands', items: CATALOG.shoes.brands };
  }

  // ═══ SHOES — CATEGORIES / TYPES ═══════════════════════════
  if (isShoe) {
    if (isMen) return { type: 'categories', domain: "Men's Shoes & Footwear — All Types", sections: CATALOG.shoes.men };
    if (isWomen) return { type: 'categories', domain: "Women's Shoes & Footwear — All Types", sections: CATALOG.shoes.women };
    if (isKids) return { type: 'categories', domain: "Kids' Shoes & Footwear — All Types", sections: CATALOG.shoes.kids };
    if (q.includes('loafer')) return { type: 'categories', domain: 'Loafer Categories', items: ["Men's Loafers & Moccasins","Women's Loafers & Moccasins","Boys' Loafers & Moccasins","Girls' Loafers & Moccasins"] };
    if (q.includes('sneaker')) return { type: 'categories', domain: 'Sneaker Categories', items: ["Men's Sneakers","Women's Sneakers","Boys' Sneakers","Girls' Sneakers"] };
    if (q.includes('boot')) return { type: 'categories', domain: 'Boot Categories', items: ["Men's Casual Boots","Women's Boots","Boys' Boots","Girls' Boots","Baby Boots & Booties","Men's Hunting Boots","Women's Hunting Boots"] };
    if (q.includes('sandal')) return { type: 'categories', domain: 'Sandal Categories', items: ["Men's Sandals & Floaters","Women's Flat Sandals","Women's Heeled Sandals","Women's Wedges","Boys' Athletic Sandals","Boys' Beach Sandals"] };
    return {
      type: 'categories', domain: 'All Shoe & Footwear Types',
      sections: {
        "Men's": ['Sneakers','Loafers & Moccasins','Boots','Boat Shoes','Oxford/Derby/Brogue','Running','Training','Walking','Trekking','Football','Cricket','Golf','Bowling & more','Sandals','Flip Flops','Slides','Ethnic / Jutti'],
        "Women's": ['Sneakers','Loafers','Boots','Ballet Flats','Espadrilles','Heels','Wedges','Pumps','Flat Sandals','Running','Training','Trekking & more'],
        "Kids'": ['Boys & Girls: Sneakers, Loafers, Running, School Shoes, Sports & more','Baby: First Walking Shoes, Boots & Booties'],
      },
    };
  }

  // ═══ APPAREL — BRANDS ═════════════════════════════════════
  if (isApparel && wantsBrands) {
    return { type: 'brands', domain: `${isMen ? "Men's " : isWomen ? "Women's " : ''}Clothing Brands`, items: CATALOG.apparel.brands, note: 'Many more brands available. Search by brand name to explore.' };
  }

  // ═══ APPAREL — CATEGORIES ══════════════════════════════════
  if (isApparel) {
    if (isMen) return { type: 'categories', domain: "Men's Clothing — All Categories", sections: CATALOG.apparel.men };
    if (isWomen) return { type: 'categories', domain: "Women's Clothing — All Categories", sections: CATALOG.apparel.women };
    if (isKids) return { type: 'categories', domain: "Kids' Clothing — All Categories", sections: CATALOG.apparel.kids };
    if (/tshirt|t-shirt|t shirt|tee/.test(q)) return { type: 'categories', domain: 'T-Shirt Types', items: ["Men's Round-Neck T-Shirts","Men's V-Neck T-Shirts","Men's Polo T-Shirts","Women's Tops & T-Shirts","Women's Sportswear Tees","Boys' Tees & Polos","Girls' T-Shirts"] };
    if (/kurta|ethnic/.test(q)) return { type: 'categories', domain: 'Ethnic Wear Categories', items: ["Men's Kurta","Women's Kurtas & Kurtis","Women's Sarees","Women's Salwar Suits","Women's Gowns","Women's Chunnis & Dupattas"] };
    if (/jacket/.test(q)) return { type: 'categories', domain: 'Jacket Styles', items: ["Men's Winter Jackets","Women's Winter Wear","Women's Track Jackets","Boys' Suit Jackets","Girls' Winter Coats & Jackets"] };
    if (/hoodie|sweatshirt/.test(q)) return { type: 'categories', domain: 'Hoodie & Sweatshirt Types', items: ["Men's Sweatshirts & Hoodies","Women's Sweatshirts & Hoodies","Baby Winter Hoodies","Girls' Hoodies"] };
    if (/lingerie|bra|panty|innerwear|underwear/.test(q)) return { type: 'categories', domain: 'Lingerie & Innerwear', sections: { "Women's Lingerie": CATALOG.apparel.women['Lingerie'], "Men's Innerwear": CATALOG.apparel.men['Innerwear'] } };
    if (/swimwear|swim|bikini/.test(q)) return { type: 'categories', domain: 'Swimwear Categories', items: CATALOG.apparel.women['Swimwear'] };
    return {
      type: 'categories', domain: 'All Apparel & Clothing Categories',
      sections: { "Men's": Object.keys(CATALOG.apparel.men), "Women's": Object.keys(CATALOG.apparel.women), "Kids'": Object.keys(CATALOG.apparel.kids) },
      note: "Ask 'what men's / women's / kids' clothing categories are there?' for a full breakdown.",
    };
  }

  // ═══ GENERIC BRAND LIST ════════════════════════════════════
  if (wantsBrands) {
    return {
      type: 'brands', domain: 'All Available Brands',
      sections: {
        'Smartphone Brands': CATALOG.mobile.smartphoneBrands,
        'Shoe Brands': CATALOG.shoes.brands.slice(0, 12),
        'Clothing Brands': CATALOG.apparel.brands,
        'Phone Case Brands': CATALOG.mobile.accessories.caseBrands.slice(0, 6),
        'Charger Brands': CATALOG.mobile.accessories.chargerBrands,
      },
    };
  }

  // ═══ ALL CATEGORIES (top-level fallback) ═══════════════════
  return {
    type: 'categories', domain: 'All Product Categories',
    topLevel: CATALOG.topLevel,
    breakdown: {
      '📱 Mobile Phones & Accessories': CATALOG.mobile.categories,
      "👟 Shoes & Footwear": ["Men's Shoes","Women's Shoes","Kids' Shoes (Boys, Girls, Baby)"],
      "👕 Apparel & Clothing": ["Men's Clothing","Women's Clothing","Kids' Clothing (Boys, Girls, Baby)"],
    },
    note: "Ask about any specific category for a detailed breakdown — e.g. 'what men's shoe types are there?' or 'list women's clothing categories'.",
  };
}

// ── MAIN ─────────────────────────────────────────────────────────
try {
  const query = $searchQuery;
  const intent = detectCatalogIntent(query);

  if (!intent) {
    return JSON.stringify({ isCatalogQuery: false });
  }

  const result = buildResponse(intent, query);
  result.isCatalogQuery = true;
  return JSON.stringify(result);

} catch (err) {
  return JSON.stringify({ error: err.message, isCatalogQuery: false });
}
